fn json_path(path: &Path) -> String {
    json_escape(&path.display().to_string())
}

fn write_assistant_loop_health_corpus(
    base: &Path,
    report: &Path,
    markdown: &Path,
    proof: &Path,
    expected_status: &str,
    repair_queue: usize,
) {
    write(&base.join("README.md"), "# Assistant Loop Health Corpus\n");
    write(proof, "{}\n");
    let expected = format!(
        r#"{{
        "status": "{expected_status}",
        "proofs": 1,
        "complete": 1,
        "partial": 0,
        "missing_required_input": 0,
        "missing_optional_input": 0,
        "improved": 1,
        "unchanged": 0,
        "regressed": 0,
        "unknown_movement": 0,
        "warnings": 0,
        "repair_queue": {repair_queue}
      }}"#
    );
    let cases = [
        "complete_improved",
        "partial_missing_optional",
        "missing_required_input",
        "unchanged_after_attempt",
        "regressed_after_attempt",
        "warning_heavy",
        "multi_proof",
    ]
    .into_iter()
    .map(|id| {
        format!(
            r#"{{
      "id": "{id}",
      "proofs": ["{}"],
      "expected_report": "{}",
      "expected_markdown": "{}",
      "expected": {expected}
    }}"#,
            json_path(proof),
            json_path(report),
            json_path(markdown)
        )
    })
    .collect::<Vec<_>>()
    .join(",\n");
    write(
        &base.join("corpus.json"),
        &format!(
            r#"{{
  "kind": "assistant_loop_health_corpus",
  "spec": "RIPR-SPEC-0022",
  "cases": [
{cases}
  ]
}}
"#
        ),
    );
}

