    let json = r#"{
  "summary": {"findings":2},
  "findings": [
    {"classification": "weakly_exposed", "stop_reasons": []},
    {"classification": "static_unknown", "stop_reasons": ["syntax unknown"]}
  ]
}"#;

    let counts = dogfood_class_counts(json);

